// ═══════════════════════════════════════════════════════════════════════════
//  ⚙️  ALL SETTINGS FOR THE 5 WORKFLOWS — change them only here.
//  (API keys are NOT here: they live in n8n → Credentials.)
// ═══════════════════════════════════════════════════════════════════════════
const CONFIG = {
  // Google Sheet "Job Automation": the long ID in its URL
  // https://docs.google.com/spreadsheets/d/<THIS PART>/edit
  SHEET_ID: 'YOUR_GOOGLE_SHEET_ID',

  // Gurwinder
  CANDIDATE_NAME: 'Your Name',                 // full name, used in letters and as sender name
  CANDIDATE_EMAIL: 'you@example.com',
  CANDIDATE_PHONE: '',                         // optional, shown under the letters

  // CV (PDF) in Google Drive: the ID in its share link
  // https://drive.google.com/file/d/<THIS PART>/view
  CV_DRIVE_FILE_ID: '',                        // leer = CV wird über CV_SEARCH_NAME in Manishas Drive gesucht
  CV_SEARCH_NAME: 'GurwinderCV.pdf',           // exakter Dateiname des CVs in Google Drive
  CV_FILE_NAME: 'Lebenslauf_Gurwinder.pdf',

  // Telegram notifications: chat ID of Gurwinder's chat with the bot ('' = no Telegram)
  TELEGRAM_CHAT_ID: '',   // '' = Telegram OFF, we use email instead

  // SAFETY: true = every application / follow-up email goes to CANDIDATE_EMAIL (subject shows
  // the real company address). Switch to false only after the end-to-end test.
  TEST_MODE: true,

  // ── WF1 Job Collector ──
  SEARCH_TERMS: ['Softwareentwickler', 'Web Entwickler', 'Backend Entwickler', 'PHP Entwickler', 'Laravel Entwickler', 'Fullstack Entwickler'],
  SEARCH_WHERE: '',              // e.g. 'Berlin' — '' = all of Germany
  ARBEITSZEIT: 'vz',             // vz = full time, tz = part time, ho = home office, 'vz;ho' = both
  RESULTS_PER_TERM: 50,
  PUBLISHED_WITHIN_DAYS: 7,      // only jobs published in the last N days
  MAX_NEW_JOBS_PER_RUN: 100,
  TITLE_KEYWORDS: ['developer', 'entwickler', 'programmierer', 'engineer', 'java', 'c#', '.net', 'php', 'laravel', 'backend', 'back-end', 'web', 'automation', 'automatisierung', 'software', 'fullstack', 'full-stack', 'full stack'],
  // More job sources: RSS feeds of job boards that offer RSS (never scrape sites that forbid bots)
  // e.g. { name: 'Example board', url: 'https://example.com/jobs.rss' }
  RSS_FEEDS: [],

  // ── WF2 AI Drafter ──
  OPENAI_MODEL: 'gpt-4o-mini',
  MAX_DRAFTS_PER_RUN: 15,

  // ── WF3 Sender ──
  MAX_SENDS_PER_RUN: 5,

  // ── WF4 Follow-up ──
  FOLLOWUP_1_AFTER_DAYS: 7,      // after DateApplied
  FOLLOWUP_2_AFTER_DAYS: 7,      // after FollowUp1Date (= 14 days after applying)
  MANUAL_REMINDER_AFTER_DAYS: 3, // Manual Apply: remind Gurwinder after N days, then again 7 days later
  MAX_FOLLOWUPS_PER_RUN: 10,

  // ── WF5 Weekly report ──
  WEEKLY_REPORT_EMAIL: true,     // also email the report to CANDIDATE_EMAIL

  // ── Future: Blue Card salary flag (EUR per year) ──
  BLUE_CARD_MIN_SALARY: 45934,

  // ── NZ + Australia via Adzuna API (free dev account: https://developer.adzuna.com) ──
  //    The German Arbeitsagentur API covers Germany only. Adzuna covers NZ + Australia (and more).
  //    (A WF1 'Adzuna job search' HTTP node must be added — see setup guide. Fill these keys first.)
  ADZUNA_APP_ID: '',                 // from your free Adzuna developer account
  ADZUNA_APP_KEY: '',                // from your free Adzuna developer account
  ADZUNA_COUNTRIES: ['nl', 'au', 'nz'],    // nz = New Zealand, au = Australia
  ADZUNA_SEARCH_TERMS: ['PHP developer', 'Laravel developer', 'Backend developer', 'Web developer', 'Full stack developer', 'Automation developer'],
  ADZUNA_RESULTS_PER_TERM: 50,
  ADZUNA_BASE: 'https://api.adzuna.com/v1/api/jobs',

  // Official API addresses (normally unchanged)
  BA_API_BASE: 'https://rest.arbeitsagentur.de/jobboerse/jobsuche-service',
  OPENAI_URL: 'https://api.openai.com/v1/chat/completions',
};

const missing = [];
if (!CONFIG.SHEET_ID || CONFIG.SHEET_ID.startsWith('PASTE_')) missing.push('SHEET_ID');
if (missing.length) throw new Error('CONFIG: please fill in ' + missing.join(', ') + ' in the CONFIG node.');
return $input.all().map((item) => ({ json: { ...item.json, config: CONFIG } }));

// ── shared helpers (same in every Code node) ──────────────────────────────
const C = $('CONFIG').first().json.config;
const TZ = 'Europe/Berlin';
function todayISO() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}
function nowStamp() {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date()).map((x) => [x.type, x.value]));
  return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}`;
}
/** Accepts 2026-10-13, 13.10.2026, 10/13/2026 or a Google Sheets serial number. Returns a UTC midnight Date or null. */
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && isFinite(v)) return new Date(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000);
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[1] - 1, +m[2]));
  return null;
}
function daysSince(v) {
  const d = parseDate(v);
  return d ? Math.round((parseDate(todayISO()) - d) / 86400000) : null;
}
function deDate(v) {
  const d = parseDate(v);
  return d ? `${String(d.getUTCDate()).padStart(2, '0')}.${String(d.getUTCMonth() + 1).padStart(2, '0')}.${d.getUTCFullYear()}` : String(v || '');
}
function validEmail(s) {
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/i.test(String(s || '').trim());
}
/** Telegram messages use HTML: these three characters must be escaped. */
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function cut(s, n) {
  s = String(s ?? '');
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
}
function addNote(old, text) {
  const o = String(old || '').trim();
  return cut(o ? `${o} | ${text}` : text, 1000);
}
function sheetLink() {
  return `https://docs.google.com/spreadsheets/d/${C.SHEET_ID}`;
}
/** "Title @ Company" without a dangling "@" when the company is unknown */
function who(j) {
  return [j.JobTitle, j.Company].filter(Boolean).join(' @ ') || j.JobID;
}
/** Telegram: linked title + " — Company" (only when known) */
function jobHtml(j) {
  const t = j.JobURL ? `<a href="${esc(j.JobURL)}">${esc(cut(j.JobTitle || j.JobID, 80))}</a>` : esc(cut(j.JobTitle || j.JobID, 80));
  return j.Company ? `${t} — ${esc(cut(j.Company, 60))}` : t;
}
function logFields(workflow, action, result) {
  return { Timestamp: nowStamp(), Workflow: workflow, Action: action, Result: cut(result, 500) };
}
// ──────────────────────────────────────────────────────────────────────────

// One item per RSS feed from CONFIG.RSS_FEEDS; a single marker item when there are none.
const feeds = (C.RSS_FEEDS || []).filter((f) => f && f.url);
if (!feeds.length) return [{ json: { _noFeeds: true } }];
return feeds.map((f) => ({ json: { name: f.name || f.url, url: f.url } }));

