}
function logFields(workflow, action, result) {
  return { Timestamp: nowStamp(), Workflow: workflow, Action: action, Result: cut(result, 500) };
}
// ──────────────────────────────────────────────────────────────────────────

// One Arbeitsagentur search request per search term (official Jobsuche API).
const base = String(C.BA_API_BASE).replace(/\/+$/, '');
return (C.SEARCH_TERMS || []).map((term) => {
  // (URLSearchParams does not exist in the n8n Code sandbox → build the query by hand)
  // v6 (v4 was retired in Sept 2026 → HTTP 403). Only parameters known to work in v6 are sent;
  // job type (Ausbildung, Praktikum …) and the age of the posting are filtered in the next node.
  const q = { was: term, page: '1', size: String(C.RESULTS_PER_TERM || 50) };
  if (C.SEARCH_WHERE) q.wo = C.SEARCH_WHERE;
  const qs = Object.entries(q).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
  return { json: { term, url: `${base}/pc/v6/jobs?${qs}` } };
});

// ── shared helpers (same in every Code node) ──────────────────────────────
const C = $('CONFIG').first().json.config;
const TZ = 'Europe/Berlin';
function todayISO() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}
function nowStamp() {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date()).map((x) => [x.type, x.value]));
  return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}`;
}
/** Accepts 2026-10-13, 13.10.2026, 10/13/2026 or a Google Sheets serial number. Returns a UTC midnight Date or null. */
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && isFinite(v)) return new Date(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000);
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[1] - 1, +m[2]));
  return null;
}
function daysSince(v) {
  const d = parseDate(v);
  return d ? Math.round((parseDate(todayISO()) - d) / 86400000) : null;
}
function deDate(v) {
  const d = parseDate(v);
  return d ? `${String(d.getUTCDate()).padStart(2, '0')}.${String(d.getUTCMonth() + 1).padStart(2, '0')}.${d.getUTCFullYear()}` : String(v || '');
}
function validEmail(s) {
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/i.test(String(s || '').trim());
}
/** Telegram messages use HTML: these three characters must be escaped. */
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function cut(s, n) {
  s = String(s ?? '');
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
}
function addNote(old, text) {
  const o = String(old || '').trim();
  return cut(o ? `${o} | ${text}` : text, 1000);
}
function sheetLink() {
  return `https://docs.google.com/spreadsheets/d/${C.SHEET_ID}`;
}
/** "Title @ Company" without a dangling "@" when the company is unknown */
function who(j) {
  return [j.JobTitle, j.Company].filter(Boolean).join(' @ ') || j.JobID;
}
/** Telegram: linked title + " — Company" (only when known) */
function jobHtml(j) {
  const t = j.JobURL ? `<a href="${esc(j.JobURL)}">${esc(cut(j.JobTitle || j.JobID, 80))}</a>` : esc(cut(j.JobTitle || j.JobID, 80));
  return j.Company ? `${t} — ${esc(cut(j.Company, 60))}` : t;
}
function logFields(workflow, action, result) {
  return { Timestamp: nowStamp(), Workflow: workflow, Action: action, Result: cut(result, 500) };
}
// ──────────────────────────────────────────────────────────────────────────

// Normalise Arbeitsagentur + RSS jobs to one shape, keep only IT/developer roles,
// drop jobs already in the sheet (by JobID or JobURL) and duplicates within this run.
const base = String(C.BA_API_BASE).replace(/\/+$/, '');
const keywords = (C.TITLE_KEYWORDS || []).map((k) => String(k).toLowerCase());
const isIT = (title) => {
  const t = String(title || '').toLowerCase();
  return keywords.some((k) => t.includes(k));
};
const known = new Set();
for (const r of $('WF1 · Read existing jobs').all()) {
  if (r.json.JobID) known.add(String(r.json.JobID).trim());
  if (r.json.JobURL) known.add(String(r.json.JobURL).trim());
}
const stripHtml = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|div|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
// base64 of the reference number for the details URL (btoa/Buffer are not reliable in the Code sandbox)
const b64 = (s) => {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const bytes = String(s); // reference numbers are plain ASCII (e.g. 10001-1002716922-S)
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes.charCodeAt(i) << 16) | ((bytes.charCodeAt(i + 1) || 0) << 8) | (bytes.charCodeAt(i + 2) || 0);
    out += A[(n >> 18) & 63] + A[(n >> 12) & 63] + (i + 1 < bytes.length ? A[(n >> 6) & 63] : '=') + (i + 2 < bytes.length ? A[n & 63] : '=');
  }
  return out;
};
const hash = (s) => {
  let h = 5381;
  for (const ch of String(s)) h = ((h << 5) + h + ch.charCodeAt(0)) >>> 0;
  return h.toString(36);
};

const out = [];
const seen = new Set();
let total = 0, notIT = 0, already = 0, apiErrors = 0;
const take = (job) => {
  total++;
  if (!isIT(job.JobTitle)) { notIT++; return; }
  // v10: Germany-only (drop Austria) + drop non-software 'Automatisierung' roles
  const _loc = String(job.Location || '');
  if (/\bwien\b|\bgraz\b|\bbezirk\b|\bbundesland\b|\bsalzburg\b|\blinz\b|\binnsbruck\b|\bklagenfurt\b/i.test(_loc) || /ams\.at/i.test(String(job._externalUrl || '')) || /^\d{4}(\s|,)/.test(_loc.trim())) { notIT++; return; }
  if (/elektroniker|elektrotechnik|mechatronik|servicetechnik|inbetriebnah|schaltanlage|betriebstechnik|\bsps\b|robotik|maschinenbau|konstrukteur/i.test(String(job.JobTitle || ''))) { notIT++; return; }
  const keys = [job.JobID, job.JobURL].filter(Boolean);
  if (keys.some((k) => known.has(k) || seen.has(k))) { already++; return; }
  keys.forEach((k) => seen.add(k));
  out.push({ json: job });
};

// 1) Bundesagentur für Arbeit — API v6 (ergebnisliste); the old v4 field names stay as fallback
const NOT_A_JOB = /\b(ausbildung|azubi|praktik|praktikum|werkstudent|duales studium|abschlussarbeit|minijob)/i;
const maxAgeDays = Number(C.PUBLISHED_WITHIN_DAYS) || 0;
const oldest = maxAgeDays ? Date.now() - maxAgeDays * 86400000 : 0;
const title1 = (s) => (s && s === s.toUpperCase() ? s.toLowerCase().replace(/(^|[\s-])\S/g, (m) => m.toUpperCase()) : s || '');
let tooOld = 0;
const responses = $input.all();
for (const it of responses) {
  const r = it.json || {};
  if (r.error) { apiErrors++; continue; }
  for (const j of r.ergebnisliste || r.stellenangebote || []) {
    const refnr = j.referenznummer || j.refnr || j.hashId;
    if (!refnr) continue;
    const title = j.stellenangebotsTitel || j.titel || j.hauptberuf || j.beruf || '';
    if (NOT_A_JOB.test(title)) { total++; notIT++; continue; }
    const lok = Array.isArray(j.stellenlokationen) && j.stellenlokationen[0] ? (j.stellenlokationen[0].adresse || j.stellenlokationen[0]) : null;
    const ort = lok || j.arbeitsort || (Array.isArray(j.arbeitsorte) ? j.arbeitsorte[0] : null) || {};
    const von = (j.veroeffentlichungszeitraum && j.veroeffentlichungszeitraum.von) || j.aktuelleVeroeffentlichungsdatum || j.ersteVeroeffentlichungsdatum || '';
    if (oldest && von && !isNaN(Date.parse(von)) && Date.parse(von) < oldest) { total++; tooOld++; continue; }
    take({
      JobID: 'BA-' + refnr,
      Source: 'Bundesagentur',
      Company: j.firma || j.arbeitgeber || '',
      JobTitle: title,
      Location: [ort.plz, ort.ort].filter(Boolean).join(' ') || title1(ort.region) || '',
      JobURL: `https://www.arbeitsagentur.de/jobsuche/jobdetail/${refnr}`,
      DatePosted: String(von).slice(0, 10),
      _src: 'BA',
      _externalUrl: j.externeUrl || j.externeURL || '',
      _description: stripHtml(j.stellenangebotsBeschreibung || j.stellenbeschreibung || j.beschreibung || ''),
      // The v4 detail endpoint is retired. Leave empty (= no detail request) unless a working
      // path is put into CONFIG as BA_DETAILS_PATH, e.g. '/pc/v6/jobdetails'.
      _detailUrl: C.BA_DETAILS_PATH ? `${base}${String(C.BA_DETAILS_PATH).replace(/\/+$/, '')}/${b64(refnr)}` : '',
    });
  }
}
if (responses.length && apiErrors === responses.length) {
  throw new Error(`Arbeitsagentur API failed for all ${apiErrors} search terms: ${JSON.stringify(responses[0].json.error).slice(0, 300)}`);
}

// 2) RSS feeds (if any are configured)
let rss = [];
try { rss = $('WF1 · Read RSS feed').all(); } catch (e) { rss = []; }
for (const it of rss) {
  const r = it.json || {};
  if (!r.link || r.error) continue;
  const host = (String(r.link).match(/^[a-z]+:\/\/(?:www\.)?([^/:?#]+)/i) || [])[1] || 'rss';
  take({
    JobID: 'RSS-' + hash(r.guid || r.link),
    Source: 'RSS: ' + host,
    Company: r.creator || r.author || '',
    JobTitle: r.title || '',
    Location: '',
    JobURL: r.link,
    DatePosted: String(r.isoDate || '').slice(0, 10),
    _src: 'RSS',
    _description: stripHtml(r.content || r.contentSnippet || ''),
  });
}

const max = Number(C.MAX_NEW_JOBS_PER_RUN) || 100;
// nothing new: one marker item, so the run is still written to the Log tab (no Telegram)
if (!out.length) return [{ json: { _none: true, _stats: { total, notIT, already, apiErrors, tooOld, new: 0, skippedOverMax: 0 } } }];
// stats for the digest (read by the digest node)
return out.slice(0, max).map((x, i) => ({ json: { ...x.json, _stats: i === 0 ? { total, notIT, already, apiErrors, tooOld, new: Math.min(out.length, max), skippedOverMax: Math.max(0, out.length - max) } : undefined } }));

// ── shared helpers (same in every Code node) ──────────────────────────────
const C = $('CONFIG').first().json.config;
const TZ = 'Europe/Berlin';
function todayISO() {
