// One sheet row per new job: description from the job details, the company e-mail published in
// the job post (GDPR: only addresses from the post itself), VisaFlag and Language.
const job = $('WF1 · Normalise, filter, dedupe').item.json;
const d = job._src === 'BA' && !$json.JobID ? $json : {};
const stripHtml = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|div|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const description = stripHtml(d.stellenangebotsBeschreibung || d.stellenbeschreibung || job._description || '');
const text = `${job.JobTitle}\n${description}`;

// e-mail address published in the job post (prefer HR / application addresses)
const emails = [...new Set((description.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map((e) => e.replace(/[.,;:]+$/, '').toLowerCase()))]
  .filter((e) => validEmail(e) && !/^(no-?reply|donotreply|datenschutz|privacy|dsb|info@arbeitsagentur)/i.test(e));
const companyEmail = emails.find((e) => /bewerb|job|karriere|career|recruit|hr|personal|talent/i.test(e)) || emails[0] || '';

// language of the posting
const words = (re) => (text.toLowerCase().match(re) || []).length;
const en = words(/\b(the|and|you|with|our|we|will|experience|team|skills|your|for)\b/g);
const de = words(/\b(und|der|die|das|mit|für|wir|sie|ihre|erfahrung|kenntnisse|bei|einer)\b/g);
const language = en > de * 1.2 ? 'EN' : 'DE';

// visa / relocation friendliness
let visa = 'No';
if (/\b(visa|visum|sponsor(ship|ing)?|blue card|blaue karte|work permit|relocation (support|package|assistance|bonus)|umzugs(hilfe|unterstützung|kosten|pauschale)|relocation)\b/i.test(text)) visa = 'Yes';
else if (language === 'EN' || /\b(english|englisch|international(e|es|en)? team|internationally)\b/i.test(text)) visa = 'Maybe';

const notes = job._externalUrl ? `Original-Anzeige: ${job._externalUrl}` : '';
return {
  json: {
    JobID: job.JobID,
    Source: job.Source,
    Company: job.Company || d.arbeitgeber || '',
    JobTitle: job.JobTitle || d.stellenangebotsTitel || d.titel || '',
    Location: job.Location,
    JobURL: job.JobURL,
    CompanyEmail: companyEmail,
    VisaFlag: visa,
    Language: language,
    DatePosted: job.DatePosted,
    DateFound: todayISO(),
    Status: 'New',
    DraftDE: '',
    DraftEN: '',
    DateApplied: '',
    FollowUp1Date: '',
    FollowUp2Date: '',
    Notes: notes,
    Description: cut(description, 6000),
    _detailsMissing: job._src === 'BA' && !description,
  },
};

