  // 3rd failure in a row → back to "New" so it is not retried (and paid for) every 30 minutes
  const failedBefore = (String(job.Notes || '').match(/draft failed/g) || []).length;
  const giveUp = failedBefore >= 2;
  return {
    json: {
      JobID: job.JobID,
      ...(giveUp ? { Status: 'New' } : {}),
      Notes: addNote(job.Notes, `${todayISO()} draft failed: ${cut(err, 160)}${giveUp ? ' (3×: set back to New — set Selected again to retry)' : ' (stays Selected, retried next run)'}`),
      ...logFields('WF2 AI Drafter', giveUp ? 'draft failed 3×' : 'draft failed', `${job.JobID} · ${who(job)} · ${err}`),
