// Daily: which follow-ups are due?
//  Applied      + DateApplied   ≥ 7 days + FollowUp1Date empty → follow-up e-mail 1 → "Follow-up 1"
//  Follow-up 1  + FollowUp1Date ≥ 7 days + FollowUp2Date empty → follow-up e-mail 2 → "Follow-up 2"
//  Manual Apply → reminder to Gurwinder (never an e-mail to the company)
const sig = [C.CANDIDATE_NAME, C.CANDIDATE_EMAIL && !String(C.CANDIDATE_EMAIL).startsWith('PASTE_') ? C.CANDIDATE_EMAIL : '', C.CANDIDATE_PHONE].filter(Boolean).join('\n');
const letter = (n, j) => {
  const en = String(j.Language || '').toUpperCase() === 'EN';
  const when = en ? String(j.DateApplied || '') : deDate(j.DateApplied);
  if (en)
    return n === 1
      ? `Dear Sir or Madam,\n\non ${when} I applied for the position "${j.JobTitle}". I would like to kindly ask whether my application has arrived and how the process is going. I am happy to send further information or a short work sample.\n\nKind regards\n${sig}`
      : `Dear Sir or Madam,\n\nI am following up once more on my application for "${j.JobTitle}" from ${when}. I am still very interested in the position and in contributing to your team. Please let me know if you need anything else from me.\n\nKind regards\n${sig}`;
  return n === 1
    ? `Sehr geehrte Damen und Herren,\n\nam ${when} habe ich mich auf die Stelle „${j.JobTitle}“ beworben. Ich möchte freundlich nachfragen, ob meine Unterlagen angekommen sind und wie der aktuelle Stand ist. Gern sende ich Ihnen weitere Informationen oder eine kurze Arbeitsprobe.\n\nMit freundlichen Grüßen\n${sig}`
    : `Sehr geehrte Damen und Herren,\n\nich melde mich noch einmal zu meiner Bewerbung vom ${when} als „${j.JobTitle}“. Ich bin weiterhin sehr an der Stelle interessiert und würde mich freuen, mein Können in Ihr Team einzubringen. Benötigen Sie noch etwas von mir?\n\nMit freundlichen Grüßen\n${sig}`;
};
if (C.TEST_MODE && !validEmail(C.CANDIDATE_EMAIL)) throw new Error('TEST_MODE is on, but CANDIDATE_EMAIL in CONFIG is not a valid address.');
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.JobID) continue;
  const status = String(j.Status || '').trim();
  const company = String(j.CompanyEmail || '').trim();
  const en = String(j.Language || '').toUpperCase() === 'EN';
  const mail = (n) => {
    let subject = en ? `Follow-up: application for ${j.JobTitle}` : `Nachfrage: Bewerbung als ${j.JobTitle}`;
    if (C.TEST_MODE) subject = `[TEST → ${company}] ${subject}`;
    return { _to: C.TEST_MODE ? String(C.CANDIDATE_EMAIL).trim() : company, _subject: cut(subject, 200), _body: letter(n, j) };
  };
  if (status === 'Applied' && validEmail(company) && !j.FollowUp1Date && (daysSince(j.DateApplied) ?? -1) >= C.FOLLOWUP_1_AFTER_DAYS) {
    out.push({ json: { ...j, _route: 0, _n: 1, ...mail(1) } });
  } else if (status === 'Follow-up 1' && validEmail(company) && !j.FollowUp2Date && (daysSince(j.FollowUp1Date) ?? -1) >= C.FOLLOWUP_2_AFTER_DAYS) {
    out.push({ json: { ...j, _route: 0, _n: 2, ...mail(2) } });
  } else if (status === 'Manual Apply' && !j.FollowUp1Date && (daysSince(j.DateFound) ?? 999) >= C.MANUAL_REMINDER_AFTER_DAYS) {
    out.push({ json: { ...j, _route: 1, _n: 1 } });
  } else if (status === 'Manual Apply' && j.FollowUp1Date && !j.FollowUp2Date && (daysSince(j.FollowUp1Date) ?? -1) >= 7) {
    out.push({ json: { ...j, _route: 1, _n: 2 } });
  }
}
return out.slice(0, Number(C.MAX_FOLLOWUPS_PER_RUN) || 10);

