// Monday report: numbers per status + this week's activity.
const rows = $input.all().map((i) => i.json).filter((r) => r.JobID);
const order = ['New', 'Selected', 'Draft Ready', 'Approved', 'Applied', 'Follow-up 1', 'Follow-up 2', 'Interview', 'Offer', 'Rejected', 'Manual Apply'];
const by = {};
for (const r of rows) {
  const s = String(r.Status || 'New').trim() || 'New';
  by[s] = (by[s] || 0) + 1;
}
const inLast7 = (v) => { const d = daysSince(v); return d !== null && d >= 0 && d < 7; };
const foundWeek = rows.filter((r) => inLast7(r.DateFound)).length;
const appliedWeek = rows.filter((r) => inLast7(r.DateApplied)).length;
const visaYes = rows.filter((r) => r.VisaFlag === 'Yes').length;
const applied = ['Applied', 'Follow-up 1', 'Follow-up 2', 'Interview', 'Offer', 'Rejected'].reduce((n, s) => n + (by[s] || 0), 0);
const answered = (by.Interview || 0) + (by.Offer || 0) + (by.Rejected || 0);
const lines = [...order, ...Object.keys(by).filter((s) => !order.includes(s))].filter((s) => by[s]).map((s) => `${s}: ${by[s]}`);
const summary = `${rows.length} jobs · this week ${foundWeek} found, ${appliedWeek} applied · ${applied} applications in total, ${answered} answered (${by.Interview || 0} interviews, ${by.Offer || 0} offers)`;
const text = `Weekly job report — ${todayISO()}\n\n${summary}\n\nBy status:\n${lines.map((l) => '  ' + l).join('\n')}\n\nVisa-friendly jobs in the sheet: ${visaYes}\n\nSheet: ${sheetLink()}`;
return [{
  json: {
    ...logFields('WF5 Weekly Report', 'weekly report', summary),
    _subject: `Weekly job report ${todayISO()}: ${appliedWeek} applied, ${by.Interview || 0} interviews`,
    _body: text,
    _tg: cut(`📊 <b>Weekly job report</b>\n\n${esc(summary)}\n\n${lines.map((l) => '• ' + esc(l)).join('\n')}\n\nVisa-friendly in the sheet: ${visaYes}\n${esc(sheetLink())}`, 4000),
  },
}];

// Error alert (also works when CONFIG itself is broken: then only the n8n execution list shows it).
let C = {};
try { C = $('CONFIG').first().json.config || {}; } catch (e) {}
const e = $json.errorData || {};
const exec = e.execution || {};
const wf = e.workflow || {};
const msg = (exec.error && (exec.error.message || exec.error.description)) || (e.trigger && e.trigger.error && e.trigger.error.message) || 'unknown error';
const node = exec.lastNodeExecuted || (e.trigger && e.trigger.error && e.trigger.error.node && e.trigger.error.node.name) || '?';
const stamp = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', dateStyle: 'short', timeStyle: 'short' }).format(new Date());
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{
  json: {
    Timestamp: stamp,
    Workflow: 'Error',
    Action: `failed at: ${node}`,
    Result: String(msg).slice(0, 500),
    _tg: `🚨 <b>Job automation error</b>\nNode: ${esc(node)}\n${esc(String(msg).slice(0, 800))}${exec.url ? `\n${esc(exec.url)}` : ''}`,
